def is_power_of_5(x):
    if x <= 0:
        return False
    while x > 1 and x % 5 == 0:
        x //= 5
    return x == 1

results = []
for n in range(3, 21):
    X = 2**n - 3
    if is_power_of_5(X):
        k = 0
        temp_X = X
        while temp_X > 1:
            temp_X //= 5
            k += 1
        results.append((n, k))

print(results)

